    "path": "client/agnes.client.json",
    "content": "{\n  \"client\": {\n    \"entry\": \"./index.js\",\n    \"styles\": [],\n    \"slots\": [],\n    \"publicConfig\": {\n      \"label\": \"my-agh-plugin\"\n    },\n    \"services\": [\"pluginmyaghplugin.list\", \"pluginmyaghplugin.change\"],\n    \"projections\": [],\n    \"id\": \"my-agh-plugin\",\n    \"lifetime\": \"profile\",\n    \"homeEntries\": [\n      {\n        \"id\": \"my-agh-plugin\",\n        \"placement\": \"secondary\",\n        \"navigation\": {\n          \"title\": \"my-agh-plugin\",\n          \"titles\": {\n            \"zh-CN\": \"my-agh-plugin\"\n          },\n          \"icon\": \"plugin\",\n          \"order\": 50\n        }\n      }\n    ]\n  }\n}\n"
